// POM68K — known divergences of a CPU vector corpus, by name.
//
// A corpus generated by an oracle holds, here and there, a vector on which the
// fork deliberately does NOT follow that oracle: an open ruling (oracle/fuzz/
// disputes/NOTES.md), or a ruling taken for a manual against the oracle.
// Dropping such vectors from the corpus hides them, and letting them fail
// makes the gate red for a decision, not for a defect. This list is the third
// way, shared by sst68030 and sst68040 (`--known FILE`):
//
//   - one vector name per line, '#' comments, grouped by ruling;
//   - a listed vector that FAILS is counted apart, neither pass nor failure;
//   - a listed vector that PASSES fails the run — the ruling was settled, or
//     something moved: the list must describe the tree, not excuse it;
//   - a listed name the corpus does not hold fails a whole-corpus run.
//
// A typed line is stricter: `@D23a <hex physical frame base> | <name>` or
// `@D12 <hex physical frame base> <hex instruction address> | <name>`.
// The harness replaces only the oracle's declared frame bytes with their
// manual-defined values and then compares the entire final state. A stale
// oracle frame or any unrelated difference fails instead of being excused.
//
// `@SR <hex manual SR> | <name>` (sst68000 only, which accepts nothing
// else): the corpus's final SR must differ from the manual's in X and C
// only; the harness puts the manual's value in its place and compares the
// entire final state. A vector listed so is counted as ruled when it then
// passes and fails otherwise; the core is held to the manual, not excused.
//
// `@OPEN <ruling> | <name>`: a ruling taken for a manual against the corpus
// (or a question the manual leaves open) on which this core currently agrees
// with the corpus. The vector is counted apart as open — never as agreement,
// never as ruled — and it must keep agreeing: one that stops agreeing (moved
// a third way, or now follows the manual: then list it plainly) fails, as a
// name the corpus does not hold does. TODO.md names each open item.
#pragma once

#include <cstdio>
#include <cstdint>
#include <fstream>
#include <map>
#include <optional>
#include <set>
#include <sstream>
#include <string>

namespace sstknown {

enum class FrameKind { ExternalFpu, Group2 };
struct FrameRule {
    FrameKind kind;
    uint32_t base, instruction;
};

class List {
public:
    // False when the file cannot be opened.
    bool load(const std::string& path) {
        std::ifstream in(path);
        if (!in) return false;
        for (std::string line; std::getline(in, line);) {
            while (!line.empty() && (line.back() == '\r' || line.back() == ' ' ||
                                     line.back() == '\t'))
                line.pop_back();
            if (line.empty() || line[0] == '#') continue;
            if (line.rfind("@SR ", 0) == 0) {
                std::istringstream row(line.substr(4));
                std::string separator, name;
                unsigned sr = 0;
                if (!(row >> std::hex >> sr) || sr > 0xFFFF ||
                    !(row >> separator) || separator != "|") return false;
                std::getline(row >> std::ws, name);
                if (name.empty() || !names_.insert(name).second) return false;
                sr_.emplace(name, uint16_t(sr));
            } else if (line.rfind("@OPEN ", 0) == 0) {
                std::istringstream row(line.substr(6));
                std::string ruling, separator, name;
                if (!(row >> ruling >> separator) || separator != "|" ||
                    ruling.size() < 2 || ruling[0] != 'D') return false;
                std::getline(row >> std::ws, name);
                if (name.empty() || !names_.insert(name).second) return false;
                open_.emplace(name, ruling);
            } else if (line[0] == '@') {
                std::istringstream row(line);
                std::string tag, separator, name;
                uint64_t frame = 0, instruction = 0;
                if (!(row >> tag >> std::hex >> frame) ||
                    (tag != "@D23a" && tag != "@D12") || frame > 0xFFFFFF || (frame & 1))
                    return false;
                if (tag == "@D12" && (!(row >> instruction) ||
                    instruction > 0xFFFFFFFFu || (instruction & 1))) return false;
                if (!(row >> separator) || separator != "|")
                    return false;
                std::getline(row >> std::ws, name);
                if (name.empty() || !names_.insert(name).second) return false;
                frames_.emplace(name, FrameRule{tag == "@D23a" ? FrameKind::ExternalFpu :
                    FrameKind::Group2, uint32_t(frame), uint32_t(instruction)});
            } else {
                if (frames_.count(line) || open_.count(line)) return false;
                names_.insert(line);
            }
        }
        loaded_ = true;
        return true;
    }
    bool active() const { return loaded_; }
    bool hasFrames() const { return !frames_.empty(); }
    bool hasExternalFrames() const {
        for (const auto& [name, rule] : frames_)
            if (rule.kind == FrameKind::ExternalFpu) return true;
        return false;
    }
    // Only @SR lines: the one form sst68000 takes.
    bool onlySrRules() const { return loaded_ && sr_.size() == names_.size(); }
    std::optional<uint16_t> srRule(const std::string& name) const {
        const auto it = sr_.find(name);
        if (it == sr_.end()) return std::nullopt;
        return it->second;
    }
    std::optional<FrameRule> frameRule(const std::string& name) const {
        const auto it = frames_.find(name);
        if (it == frames_.end()) return std::nullopt;
        return it->second;
    }

    // Whether `name` is listed; a listed name is remembered as met. An @SR
    // name answers false: it excuses nothing, its SR is substituted instead;
    // so does an @OPEN name, which `open` answers.
    bool listed(const std::string& name) {
        if (!loaded_ || !names_.count(name)) return false;
        seen_.insert(name);
        return !sr_.count(name) && !open_.count(name);
    }
    // The ruling of an @OPEN name (met by `listed`), or nothing.
    std::optional<std::string> open(const std::string& name) const {
        const auto it = open_.find(name);
        if (it == open_.end()) return std::nullopt;
        return it->second;
    }

    // Listed names the run never met; prints up to `examples` of them.
    long reportMissing(int examples) const {
        long missing = 0;
        for (const std::string& name : names_) {
            if (seen_.count(name)) continue;
            if (missing++ < examples)
                std::printf("        x \"%s\"  listed in --known but absent "
                            "from the corpus\n", name.c_str());
        }
        return missing;
    }

    static constexpr const char* kStale = "listed in --known but passes: remove it";
    static constexpr const char* kOpenMoved =
        "listed @OPEN (agrees with the corpus) but differs now; list it plainly if it follows the manual: ";

private:
    std::set<std::string> names_, seen_;
    std::map<std::string, FrameRule> frames_;
    std::map<std::string, uint16_t> sr_;
    std::map<std::string, std::string> open_;   // @OPEN name -> ruling
    bool loaded_ = false;
};

// Retain raw fixtures. Validate the old oracle contract before replacing
// exactly the fields ruled against it; every other state comparison stays live.
template<class Vector>
bool normalizeFrame(Vector& v, const FrameRule& rule, std::string& why) {
    const uint32_t frame = rule.base;
    auto byte = [&](uint32_t addr) -> uint8_t {
        addr &= 0xFFFFFF;
        for (const auto& c : v.fin.ram) if ((c.addr & 0xFFFFFF) == addr) return c.val;
        for (const auto& c : v.initial.ram) if ((c.addr & 0xFFFFFF) == addr) return c.val;
        return 0;
    };
    auto longword = [&](uint32_t addr) {
        return uint32_t(byte(addr)) << 24 | uint32_t(byte(addr + 1)) << 16 |
               uint32_t(byte(addr + 2)) << 8 | byte(addr + 3);
    };
    const uint16_t format = uint16_t(byte(frame + 6) << 8 | byte(frame + 7));
    const bool external = rule.kind == FrameKind::ExternalFpu;
    if (external ? (!v.initial.hasFp || format < 0x30C0 || format > 0x30DC || (format & 3)) :
        ((format != 0x2014 && format != 0x2018 && format != 0x201C) ||
         longword(frame + 8) != longword(frame + 2) || rule.instruction == longword(frame + 2))) {
        why = external ? "D23a rule requires an oracle format-3 FPU frame (stale or invalid rule)" :
                         "D12 rule requires an oracle group-2 frame with IA=resume PC (stale or invalid rule)";
        return false;
    }
    auto put = [&](uint32_t addr, uint8_t value) {
        addr &= 0xFFFFFF;
        for (auto& c : v.fin.ram) if ((c.addr & 0xFFFFFF) == addr) { c.val = value; return; }
        v.fin.ram.push_back({addr, value});
    };
    if (external) put(frame + 6, 0x20);
    const uint32_t instruction = external ? v.initial.pc : rule.instruction;
    for (int i = 0; i < 4; ++i)
        put(frame + 8 + i, uint8_t(instruction >> (24 - 8 * i)));
    return true;
}

}  // namespace sstknown
